HTML_TEMPLATE = r"""<!doctype html>
<html lang="ko">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>OMF-MES 데이터 모델 × API 계약</title>
<style>
:root{--canvas:#f4f7fa;--paper:#fff;--ink:#142033;--muted:#667386;--line:#dbe3eb;--blue:#2563eb;--blue2:#dbeafe;--orange:#c96d1d;--green:#16827a;--violet:#7456c8;--red:#c43d3d;--shadow:0 10px 34px rgba(29,49,74,.10);--radius:16px}
*{box-sizing:border-box}html,body{margin:0;height:100%;font-family:Pretendard,"Noto Sans KR",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:var(--canvas)}button,input,select{font:inherit}button{cursor:pointer}.app{height:100%;display:grid;grid-template-rows:auto 1fr;overflow:hidden}
header{background:rgba(255,255,255,.96);border-bottom:1px solid var(--line);padding:18px 24px 0;z-index:4}.headrow{display:flex;align-items:flex-start;justify-content:space-between;gap:24px}.eyebrow{font-size:11px;letter-spacing:.14em;font-weight:800;color:var(--blue);text-transform:uppercase}.title{font-size:24px;font-weight:780;letter-spacing:-.035em;margin-top:5px}.subtitle{font-size:13px;color:var(--muted);margin-top:5px}.metrics{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.metric{border:1px solid var(--line);border-radius:999px;padding:7px 11px;background:#fafcff;font-size:12px;white-space:nowrap}.metric strong{color:var(--blue);font-variant-numeric:tabular-nums}.tabs{display:flex;gap:24px;margin-top:17px}.tab{border:0;background:transparent;padding:11px 2px 13px;color:var(--muted);font-weight:700;font-size:13px;border-bottom:3px solid transparent}.tab.active{color:var(--ink);border-color:var(--blue)}
.view{display:none;height:100%;min-height:0}.view.active{display:grid}.toolbar{display:flex;align-items:center;gap:9px}.search{height:38px;min-width:245px;border:1px solid var(--line);border-radius:10px;background:#fff;padding:0 12px;outline:none}.search:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(37,99,235,.1)}select,.mini-btn{height:38px;border:1px solid var(--line);border-radius:10px;background:#fff;padding:0 11px;color:var(--ink)}.mini-btn{min-width:38px}.badge{display:inline-flex;align-items:center;border-radius:7px;padding:4px 7px;font-size:10px;font-weight:800;letter-spacing:.03em}.method-GET{background:#dbeafe;color:#1859b8}.method-POST{background:#dcfce7;color:#08704a}.method-PUT,.method-PATCH{background:#ffedd5;color:#a34c08}.method-DELETE{background:#fee2e2;color:#a72a2a}
#modelView{grid-template-columns:1fr 340px;min-height:0}.stage-wrap{min-width:0;min-height:0;display:grid;grid-template-rows:auto 1fr;padding:14px 0 14px 18px}.stage-toolbar{padding:0 14px 12px 0;display:flex;justify-content:space-between;align-items:center;gap:12px}.legend{display:flex;gap:12px;font-size:11px;color:var(--muted)}.dot{width:8px;height:8px;border-radius:50%;display:inline-block;margin-right:4px}.stage{position:relative;overflow:hidden;background:#eef3f7;border:1px solid var(--line);border-radius:var(--radius);box-shadow:inset 0 1px 0 #fff}.stage svg{width:100%;height:100%;touch-action:none}.graph-bg{fill:#eef3f7}.schema-box{fill:#f9fbfd;stroke:#cbd6e1;stroke-width:2}.schema-label{font-size:23px;font-weight:800;fill:#29384b}.schema-count{font-size:13px;fill:#7c8998}.node rect{fill:#fff;stroke:#cfd9e3;stroke-width:2;filter:drop-shadow(0 3px 5px rgba(30,50,70,.07))}.node text{font-size:14px;font-weight:650;fill:#1d2b3c;pointer-events:none}.node .logical{font-size:11px;font-weight:500;fill:#718095}.node.partition rect{fill:#f8fafc;stroke-dasharray:5 4}.node.dim{opacity:.16}.node.selected rect{stroke:var(--blue);stroke-width:4;fill:#eff6ff}.node.neighbor rect{stroke:var(--green);stroke-width:3}.edge{fill:none;stroke:#aebbc8;stroke-width:1;opacity:.16}.edge.active{stroke:var(--blue);stroke-width:3;opacity:.9}.edge.incoming{stroke:var(--violet)}.empty-state{padding:28px;color:var(--muted);text-align:center}.side{padding:14px 18px 18px 14px;min-height:0}.panel{height:100%;background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:18px;overflow:auto}.panel h2{font-size:18px;margin:0 0 6px;letter-spacing:-.02em}.qualified{font-family:"SFMono-Regular",Consolas,monospace;color:var(--blue);font-size:12px;overflow-wrap:anywhere}.purpose{font-size:13px;color:var(--muted);line-height:1.6;margin:16px 0}.kv{display:grid;grid-template-columns:88px 1fr;gap:8px 10px;font-size:12px;padding:12px 0;border-top:1px solid var(--line)}.kv dt{color:var(--muted)}.kv dd{margin:0;overflow-wrap:anywhere}.relation-list{display:grid;gap:7px}.relation-link{border:1px solid var(--line);border-radius:9px;background:#fafcff;padding:9px;text-align:left;font-size:11px;color:var(--ink);width:100%}.relation-link:hover{border-color:#93b5ed;background:#f1f6ff}
#apiView{grid-template-columns:360px minmax(420px,1fr) 430px;min-height:0}.api-list-pane,.api-detail-pane,.table-pane{min-height:0;padding:14px}.api-list-pane{padding-right:0}.api-detail-pane{padding-right:0}.pane{height:100%;background:#fff;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow);display:grid;grid-template-rows:auto 1fr}.pane-head{padding:15px;border-bottom:1px solid var(--line);background:#fbfcfe}.pane-head .toolbar{display:grid;grid-template-columns:1fr auto}.pane-head .search{min-width:0;width:100%}.api-list{overflow:auto;padding:7px}.api-item{width:100%;border:1px solid transparent;border-radius:10px;background:transparent;text-align:left;padding:10px;display:grid;grid-template-columns:54px 1fr;gap:8px;align-items:start}.api-item:hover{background:#f5f8fc}.api-item.active{background:#edf4ff;border-color:#b8d0f7}.api-path{font:11px/1.45 "SFMono-Regular",Consolas,monospace;overflow-wrap:anywhere}.api-summary{font-size:11px;color:var(--muted);margin-top:3px}.detail-scroll{overflow:auto;padding:24px}.detail-top{display:flex;align-items:center;gap:10px}.detail-path{font:16px/1.5 "SFMono-Regular",Consolas,monospace;font-weight:700;overflow-wrap:anywhere}.detail-summary{font-size:24px;font-weight:760;letter-spacing:-.035em;margin:22px 0 8px}.detail-domain{font-size:12px;color:var(--muted)}.contract-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:22px 0}.contract-card{background:#f7f9fc;border:1px solid var(--line);border-radius:12px;padding:12px}.contract-card b{display:block;font-size:11px;color:var(--muted);margin-bottom:6px}.contract-card span{font-size:13px;font-weight:700}.flow{margin-top:24px}.flow h3,.table-pane h3{font-size:13px;margin:0 0 10px}.flow-row{display:grid;grid-template-columns:10px 1fr auto;gap:9px;align-items:start;padding:10px 0;border-top:1px solid var(--line)}.flow-line{width:3px;height:100%;min-height:32px;background:var(--blue);border-radius:3px;margin-left:3px}.flow-table{font:12px "SFMono-Regular",Consolas,monospace}.flow-meta{font-size:10px;color:var(--muted);margin-top:4px}.access{font-size:10px;font-weight:800;color:var(--orange)}.table-scroll{overflow:auto;padding:14px}.table-card{border:1px solid var(--line);border-radius:13px;padding:14px;margin-bottom:11px;background:#fff;position:relative;overflow:hidden}.table-card:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--blue)}.table-card.support:before{background:var(--green)}.table-card.cross:before{background:var(--violet)}.table-card .name{font:12px "SFMono-Regular",Consolas,monospace;color:var(--blue);font-weight:700}.table-card .lname{font-size:15px;font-weight:760;margin:5px 0}.table-card .desc{font-size:11px;color:var(--muted);line-height:1.5}.column-chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:10px}.chip{font:9px "SFMono-Regular",Consolas,monospace;background:#f1f5f9;border-radius:5px;padding:4px 5px;color:#536174}.signal{position:absolute;height:2px;background:linear-gradient(90deg,transparent,var(--blue),transparent);left:0;right:0;top:0;animation:signal 2.8s ease-in-out infinite}@keyframes signal{0%{transform:translateX(-100%)}100%{transform:translateX(100%)}}
.stamp{font-size:10px;color:#8a96a5;margin-top:18px}.hidden{display:none!important}@media(max-width:1100px){#apiView{grid-template-columns:300px 1fr}.table-pane{display:none}#modelView{grid-template-columns:1fr}.side{display:none}.metrics{display:none}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}.signal{animation:none}}
</style>
</head>
<body>
<div class="app">
<header>
  <div class="headrow"><div><div class="eyebrow">Contract traceability</div><div class="title">OMF-MES 데이터 모델 × API 계약</div><div class="subtitle">설계 커밋 a8f46f2 · PostgreSQL 16 · 모델 v4.0</div></div><div class="metrics" id="metrics"></div></div>
  <nav class="tabs" aria-label="문서 보기"><button class="tab active" data-view="modelView">전체 테이블 관계도</button><button class="tab" data-view="apiView">API ↔ 테이블 검증</button></nav>
</header>
<section class="view active" id="modelView">
  <div class="stage-wrap"><div class="stage-toolbar"><div class="toolbar"><input id="tableSearch" class="search" placeholder="테이블 검색 (예: work_order)" aria-label="테이블 검색"><select id="schemaFilter" aria-label="스키마 선택"><option value="">전체 스키마</option></select><button class="mini-btn" id="fitGraph" title="전체 보기">Fit</button><button class="mini-btn" id="resetGraph" title="선택 해제">↺</button></div><div class="legend"><span><i class="dot" style="background:#2563eb"></i>선택</span><span><i class="dot" style="background:#16827a"></i>직접 관계</span><span>휠: 확대 · 드래그: 이동</span></div></div><div class="stage" id="graphStage"><svg id="graph" role="img" aria-label="전체 테이블 관계도"></svg></div></div>
  <aside class="side"><div class="panel" id="tableDetail"><div class="empty-state">테이블을 선택하면<br>목적과 직접 관계가 표시됩니다.</div></div></aside>
</section>
<section class="view" id="apiView">
  <aside class="api-list-pane"><div class="pane"><div class="pane-head"><div class="toolbar"><input class="search" id="apiSearch" placeholder="API 경로·설명 검색" aria-label="API 검색"><select id="methodFilter" aria-label="HTTP 메서드"><option value="">ALL</option><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select></div><div style="margin-top:8px"><select id="domainFilter" style="width:100%" aria-label="API 도메인"><option value="">전체 도메인</option></select></div></div><div class="api-list" id="apiList"></div></div></aside>
  <main class="api-detail-pane"><div class="pane"><div class="detail-scroll" id="apiDetail"></div></div></main>
  <aside class="table-pane"><div class="pane"><div class="pane-head"><h3>관계 테이블</h3><div style="font-size:11px;color:var(--muted)">처리 역할·접근 유형·핵심 키</div></div><div class="table-scroll" id="apiTables"></div></div></aside>
</section>
</div>
<script>
const catalog=__CATALOG_JSON__;
const mapping=__MAPPING_JSON__;
const tableMap=new Map(catalog.tables.map(t=>[t.qualified_name,t]));
const bySchema=Object.groupBy?Object.groupBy(catalog.tables,t=>t.schema):catalog.tables.reduce((a,t)=>((a[t.schema]??=[]).push(t),a),{});
const summary={tables:catalog.tables.length,logical:catalog.tables.filter(t=>!t.is_partition).length,columns:catalog.tables.reduce((n,t)=>n+t.columns.length,0),relations:catalog.relationships.length,apis:mapping.operations.length};
document.getElementById('metrics').innerHTML=[['테이블',summary.tables],['컬럼',summary.columns.toLocaleString()],['FK',summary.relations],['API',summary.apis],['매핑','100%']].map(([k,v])=>`<span class="metric">${k} <strong>${v}</strong></span>`).join('');
document.querySelectorAll('.tab').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.tab,.view').forEach(e=>e.classList.remove('active'));btn.classList.add('active');document.getElementById(btn.dataset.view).classList.add('active');if(btn.dataset.view==='modelView')setTimeout(fitGraph,30)}));
const schemaSelect=document.getElementById('schemaFilter');Object.keys(bySchema).sort().forEach(s=>schemaSelect.add(new Option(`${s} · ${bySchema[s].length}`,s)));
const domainSelect=document.getElementById('domainFilter');[...new Set(mapping.operations.map(o=>o.domain))].forEach(d=>domainSelect.add(new Option(d,d)));

// Relationship graph
const svg=document.getElementById('graph'),NS='http://www.w3.org/2000/svg';let viewport,positions=new Map(),scale=1,panX=0,panY=0,drag=null,selectedTable=null;
function el(name,attrs={}){const node=document.createElementNS(NS,name);for(const[k,v]of Object.entries(attrs))node.setAttribute(k,v);return node}
function buildGraph(){svg.replaceChildren();svg.setAttribute('viewBox','0 0 3500 3600');svg.append(el('rect',{class:'graph-bg',width:3500,height:3600}));viewport=el('g');svg.append(viewport);positions.clear();const schemas=Object.keys(bySchema).sort();const outerCols=3,boxW=1080,gapX=55,gapY=55;let colHeights=Array(outerCols).fill(25);
  schemas.forEach((schema,i)=>{const tables=bySchema[schema].slice().sort((a,b)=>a.name.localeCompare(b.name));const col=i%outerCols,x=25+col*(boxW+gapX),innerCols=3,rows=Math.ceil(tables.length/innerCols),boxH=92+rows*60,y=colHeights[col];colHeights[col]+=boxH+gapY;const g=el('g',{class:'schema-group','data-schema':schema});g.append(el('rect',{class:'schema-box',x,y,width:boxW,height:boxH,rx:18}));const label=el('text',{class:'schema-label',x:x+24,y:y+36});label.textContent=schema;g.append(label);const count=el('text',{class:'schema-count',x:x+24,y:y+61});count.textContent=`${tables.length} tables`;g.append(count);tables.forEach((t,index)=>{const innerCol=index%innerCols,row=Math.floor(index/innerCols),nx=x+22+innerCol*350,ny=y+78+row*60,nw=326,nh=45;positions.set(t.qualified_name,{x:nx,y:ny,w:nw,h:nh});const ng=el('g',{class:`node${t.is_partition?' partition':''}`,'data-table':t.qualified_name,tabindex:'0',role:'button'});ng.append(el('rect',{x:nx,y:ny,width:nw,height:nh,rx:9}));const tx=el('text',{x:nx+12,y:ny+19});tx.textContent=t.name;ng.append(tx);const lt=el('text',{class:'logical',x:nx+12,y:ny+36});lt.textContent=t.logical_name;ng.append(lt);ng.addEventListener('click',()=>selectTable(t.qualified_name));ng.addEventListener('keydown',e=>{if(e.key==='Enter')selectTable(t.qualified_name)});g.append(ng)});viewport.append(g)});
  const edgeLayer=el('g',{class:'edges'});viewport.prepend(edgeLayer);catalog.relationships.forEach((r,idx)=>{const a=positions.get(`${r.source_schema}.${r.source_table}`),b=positions.get(`${r.target_schema}.${r.target_table}`);if(!a||!b)return;const x1=a.x+a.w/2,y1=a.y+a.h/2,x2=b.x+b.w/2,y2=b.y+b.h/2,dx=Math.max(40,Math.abs(x2-x1)*.35);const p=el('path',{class:'edge','data-source':`${r.source_schema}.${r.source_table}`,'data-target':`${r.target_schema}.${r.target_table}`,d:`M${x1},${y1} C${x1+(x2>x1?dx:-dx)},${y1} ${x2-(x2>x1?dx:-dx)},${y2} ${x2},${y2}`});edgeLayer.append(p)});applyTransform()}
function selectTable(name){selectedTable=name;const related=new Set([name]);document.querySelectorAll('.edge').forEach(e=>{const active=e.dataset.source===name||e.dataset.target===name;e.classList.toggle('active',active);e.classList.toggle('incoming',active&&e.dataset.target===name);if(active){related.add(e.dataset.source);related.add(e.dataset.target)}});document.querySelectorAll('.node').forEach(n=>{n.classList.toggle('selected',n.dataset.table===name);n.classList.toggle('neighbor',n.dataset.table!==name&&related.has(n.dataset.table));n.classList.toggle('dim',!related.has(n.dataset.table))});renderTableDetail(name)}
function renderTableDetail(name){const t=tableMap.get(name);const outgoing=catalog.relationships.filter(r=>`${r.source_schema}.${r.source_table}`===name),incoming=catalog.relationships.filter(r=>`${r.target_schema}.${r.target_table}`===name);const links=[...outgoing.map(r=>({to:`${r.target_schema}.${r.target_table}`,label:`→ ${r.target_table}`,cols:r.source_columns.join(', ')})),...incoming.map(r=>({to:`${r.source_schema}.${r.source_table}`,label:`← ${r.source_table}`,cols:r.target_columns.join(', ')}))];document.getElementById('tableDetail').innerHTML=`<h2>${esc(t.logical_name)}</h2><div class="qualified">${esc(name)}</div><p class="purpose">${esc(t.purpose)}</p><dl class="kv"><dt>생명주기</dt><dd>${t.lifecycle}</dd><dt>PK</dt><dd>${esc(t.primary_key.join(', ')||'—')}</dd><dt>컬럼</dt><dd>${t.columns.length}개</dd><dt>직접 관계</dt><dd>참조 ${outgoing.length} · 피참조 ${incoming.length}</dd></dl><h3 style="font-size:12px;margin:15px 0 8px">직접 연결</h3><div class="relation-list">${links.slice(0,80).map(l=>`<button class="relation-link" data-jump="${l.to}"><b>${esc(l.label)}</b><br><span style="color:var(--muted)">${esc(l.cols)}</span></button>`).join('')||'<span style="font-size:11px;color:var(--muted)">직접 FK 없음</span>'}</div><div class="stamp">모델 v4.0 · ${t.is_partition?'물리 파티션':'논리 테이블'}</div>`;document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>selectTable(b.dataset.jump))}
function applyTransform(){viewport?.setAttribute('transform',`translate(${panX} ${panY}) scale(${scale})`)}function fitGraph(){scale=.27;panX=15;panY=10;applyTransform()}function resetGraph(){selectedTable=null;document.querySelectorAll('.node').forEach(n=>n.classList.remove('selected','neighbor','dim'));document.querySelectorAll('.edge').forEach(e=>e.classList.remove('active','incoming'));document.getElementById('tableDetail').innerHTML='<div class="empty-state">테이블을 선택하면<br>목적과 직접 관계가 표시됩니다.</div>';fitGraph()}
svg.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(.12,Math.min(1.8,scale*(e.deltaY>0?.9:1.1)));applyTransform()},{passive:false});svg.addEventListener('pointerdown',e=>{drag={x:e.clientX-panX,y:e.clientY-panY};svg.setPointerCapture(e.pointerId)});svg.addEventListener('pointermove',e=>{if(drag){panX=e.clientX-drag.x;panY=e.clientY-drag.y;applyTransform()}});svg.addEventListener('pointerup',()=>drag=null);document.getElementById('fitGraph').onclick=fitGraph;document.getElementById('resetGraph').onclick=resetGraph;
function filterTables(){const q=document.getElementById('tableSearch').value.trim().toLowerCase(),schema=schemaSelect.value;document.querySelectorAll('.node').forEach(n=>{const t=tableMap.get(n.dataset.table),match=(!q||(t.qualified_name+' '+t.logical_name).toLowerCase().includes(q))&&(!schema||t.schema===schema);n.classList.toggle('dim',!match)});document.querySelectorAll('.schema-group').forEach(g=>g.classList.toggle('hidden',schema&&g.dataset.schema!==schema))}document.getElementById('tableSearch').oninput=filterTables;schemaSelect.onchange=filterTables;

// API contract view
let selectedApi=mapping.operations[0];function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function filteredApis(){const q=document.getElementById('apiSearch').value.trim().toLowerCase(),m=document.getElementById('methodFilter').value,d=domainSelect.value;return mapping.operations.filter(o=>(!q||(o.path+' '+o.summary).toLowerCase().includes(q))&&(!m||o.method===m)&&(!d||o.domain===d))}
function renderApiList(){const list=filteredApis();document.getElementById('apiList').innerHTML=list.map(o=>`<button class="api-item ${selectedApi?.id===o.id?'active':''}" data-api="${esc(o.id)}"><span class="badge method-${o.method}">${o.method}</span><span><div class="api-path">${esc(o.path)}</div><div class="api-summary">${esc(o.summary)}</div></span></button>`).join('')||'<div class="empty-state">조건에 맞는 API가 없습니다.</div>';document.querySelectorAll('[data-api]').forEach(b=>b.onclick=()=>{selectedApi=mapping.operations.find(o=>o.id===b.dataset.api);renderApiList();renderApiDetail()})}
function renderApiDetail(){const o=selectedApi;if(!o)return;document.getElementById('apiDetail').innerHTML=`<div class="signal"></div><div class="detail-top"><span class="badge method-${o.method}">${o.method}</span><span class="detail-path">${esc(o.path)}</span></div><div class="detail-summary">${esc(o.summary||'설명 없음')}</div><div class="detail-domain">${esc(o.domain)} · ${o.tags.map(esc).join(', ')||'태그 없음'}</div><div class="contract-grid"><div class="contract-card"><b>멱등 키</b><span>${o.idempotency_key?'필수 계약':'해당 없음'}</span></div><div class="contract-card"><b>낙관적 잠금</b><span>${o.if_match?'If-Match 사용':'해당 없음'}</span></div><div class="contract-card"><b>관계 테이블</b><span>${o.tables.length}개</span></div><div class="contract-card"><b>검증 상태</b><span style="color:var(--green)">매핑 완료</span></div></div><section class="flow"><h3>처리 흐름</h3>${o.tables.map(t=>`<div class="flow-row"><i class="flow-line"></i><div><div class="flow-table">${esc(t.table)}</div><div class="flow-meta">${t.role} · ${t.basis}</div></div><span class="access">${t.access}</span></div>`).join('')}</section>`;document.getElementById('apiTables').innerHTML=o.tables.map(rel=>{const t=tableMap.get(rel.table),cls=rel.role==='PRIMARY'?'':rel.role==='CROSS_CUTTING'?'cross':'support';return `<article class="table-card ${cls}"><div class="name">${esc(t.qualified_name)}</div><div class="lname">${esc(t.logical_name)}</div><div class="desc">${esc(t.purpose)}</div><div class="column-chips">${t.primary_key.map(c=>`<span class="chip">PK ${esc(c)}</span>`).join('')}${t.foreign_keys.slice(0,4).map(f=>`<span class="chip">FK ${esc(f.columns.join(','))}</span>`).join('')}</div><div style="margin-top:10px;font-size:10px"><b>${rel.role}</b> · <span style="color:var(--orange);font-weight:800">${rel.access}</span></div></article>`}).join('')}
['apiSearch','methodFilter','domainFilter'].forEach(id=>document.getElementById(id).addEventListener(id==='apiSearch'?'input':'change',renderApiList));
buildGraph();fitGraph();renderApiList();renderApiDetail();
</script>
</body></html>"""


def render_html(catalog: dict[str, Any], mapping: dict[str, Any]) -> str:
    # Prevent embedded contract text from terminating the inline script.
    catalog_payload = json.dumps(
        catalog, ensure_ascii=False, separators=(",", ":")
    ).replace("</", "<\\/")
    mapping_payload = json.dumps(
        mapping, ensure_ascii=False, separators=(",", ":")
    ).replace("</", "<\\/")
    return HTML_TEMPLATE.replace("__CATALOG_JSON__", catalog_payload).replace(
        "__MAPPING_JSON__", mapping_payload
    )
